package cn.minidayz.patcher;
import android.app.*;import android.content.*;import android.os.*;
public final class BuildService extends Service {
 private volatile boolean running;
 public IBinder onBind(Intent intent){return null;}
 public int onStartCommand(Intent intent,int flags,int id){if(running)return START_NOT_STICKY;final Jobs jobs=Jobs.get(this);final Jobs.Work work=jobs.pending;if(work==null){stopSelf();return START_NOT_STICKY;}try{if(Build.VERSION.SDK_INT>=26){Class<?> channel=Class.forName("android.app.NotificationChannel");Object ch=channel.getConstructor(String.class,CharSequence.class,int.class).newInstance("build","本地补丁任务",2);Object manager=getSystemService(NOTIFICATION_SERVICE);manager.getClass().getMethod("createNotificationChannel",channel).invoke(manager,ch);}Notification.Builder b=Build.VERSION.SDK_INT>=26?(Notification.Builder)Notification.Builder.class.getConstructor(Context.class,String.class).newInstance(this,"build"):new Notification.Builder(this);b.setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).putExtra("studio_tab",1).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),0x0c000000));b.setContentTitle("P版补丁助手").setContentText("正在处理本地文件，可返回助手查看进度").setSmallIcon(android.R.drawable.stat_sys_download).setOngoing(true);startForeground(1,b.build());}catch(Exception e){jobs.finish(new java.io.IOException("E_FOREGROUND: 无法启动前台任务"));stopSelf();return START_NOT_STICKY;}running=true;new Thread(new Runnable(){public void run(){Exception error=null;try{work.run(jobs);}catch(Throwable e){error=e instanceof Exception?(Exception)e:new java.io.IOException("E_RUNTIME: "+e.getClass().getSimpleName());}finally{jobs.finish(error);running=false;stopForeground(true);stopSelf();}}},"local-patcher").start();return START_NOT_STICKY;}
}
